func execute() error {
	if printVersion {
		printVersionHeader()
		return nil
	}

	var err error

	cfg, err = configure(cfgPath)
	if err != nil {
		return err
	}

	var grpcTLSOptions []grpc.ServerOption
	var gatewayDialOptions = []grpc.DialOption{grpc.WithInsecure()}
	if cfg.Server.Protocol == HTTPS {
		certificate, err := tls.LoadX509KeyPair(cfg.Server.CertFile, cfg.Server.CertKey)
		if err != nil {
			return errors.Wrap(err, "loading TLS certificate")
		}
		grpcTLSOptions = append(grpcTLSOptions, grpc.Creds(credentials.NewTLS(&tls.Config{
			Certificates: []tls.Certificate{certificate},
		})))

		// The gateway connects to the local gRPC listener using the configured
		// certificate as its trust anchor.
		rootCAs := x509.NewCertPool()
		certPEM, err := os.ReadFile(cfg.Server.CertFile)
		if err != nil {
			return err
		}
		if !rootCAs.AppendCertsFromPEM(certPEM) {
			return errors.New("loading TLS certificate: no certificates found")
		}
		leaf, err := x509.ParseCertificate(certificate.Certificate[0])
		if err != nil {
			return errors.Wrap(err, "parsing TLS certificate")
		}
		serverName := cfg.Server.Host
		if len(leaf.DNSNames) > 0 {
			serverName = leaf.DNSNames[0]
		} else if len(leaf.IPAddresses) > 0 {
			serverName = leaf.IPAddresses[0].String()
		}
		gatewayDialOptions = []grpc.DialOption{grpc.WithTransportCredentials(credentials.NewTLS(&tls.Config{
			RootCAs:    rootCAs,
			ServerName: serverName,
		}))}
	}

	lvl, err := logrus.ParseLevel(cfg.LogLevel)
